"""Install previously published recovery payload and hand it to the existing own allocation."""
import base64,hashlib,json,shutil,subprocess,time
from pathlib import Path
PAYLOAD={'native_resume.py': '', 'run.sh': '', 'README.md': '', 'prepare.py': ''}
B=Path('/dataset/shaoshitong/recursive-bran-a-h100-20261012');R=B/'recovery-from100-20261013';S=R/'source-resume100-v1'
assert not (R/'deployment.json').exists(),'Already deployed; inspect original receipt'
job=subprocess.check_output(['scontrol','show','job','3393'],text=True)
assert 'JobState=RUNNING' in job and 'NodeList=h100-11' in job
assert (R/'allocation-job.txt').read_text().strip()=='3393'
assert not Path('/proc/3714909').exists()
old=B/'source-71d4e69';native=(old/'search_r1/baselines/recursive_a_schedule_resume.py').read_text()
assert hashlib.sha256(native[native.index('def parent_manifest():'):].encode()).hexdigest()=='d3a63257599028dab4e3b5993181b3954ca35cfe1db3823172471f121a74ebad'
shutil.copytree(old,S,symlinks=True,ignore=shutil.ignore_patterns('__pycache__','*.pyc','.git'))
folder=S/'release/recursive_bran_a/h100_resume100_v1';folder.mkdir(parents=True)
manifest={}
for name,encoded in PAYLOAD.items():
 raw=base64.b64decode(encoded);p=folder/name;p.write_bytes(raw);assert p.read_bytes()==raw;manifest[str(p)]=hashlib.sha256(raw).hexdigest()
(S/'search_r1/baselines/recursive_a_schedule_resume.py').write_bytes((folder/'native_resume.py').read_bytes())
launch='#!/bin/bash\nexport RBA_RECOVERY_SOURCE_COMMIT=a1ec638baked\nset +e\nbash '+str(folder/'run.sh')+'\nrc=$?\nprintf "%s\\n" "$rc" > '+str(R/'actual-entry-exit.txt')+'\n# Keep our own allocation for diagnosis/final scoring; never restart blindly.\nwhile true; do sleep 60; done\n'
# Exact published code identity, independent from inherited old runtime source.
launch=launch.replace('a1ec638baked','a1ec638575268747468b1a14ff8fd5f858ca0e1a')
receipt=dict(time=time.time(),job=3393,source_commit='a1ec638575268747468b1a14ff8fd5f858ca0e1a',inherited_source=str(old),source=str(S),manifest=manifest,parent_checkpoint=100,phase='READY_FOR_ALLOCATION_SETUP_NOT_TRAINING')
(R/'deployment.json').write_text(json.dumps(receipt,indent=2))
ready=R/'launch-ready.sh';ready.write_text(launch)
print(json.dumps(receipt),flush=True)
